-- 103 affordable cars from 10 brands (Dacia, Toyota, Volkswagen, Skoda, Renault, Hyundai, Kia, Opel, Peugeot, Nissan),
-- 3 models each and 8 to 15 cars per brand, with Romanian and Russian descriptions.
-- Photos come from Wikimedia Commons under free licences and are served from the site (public/cars/);
-- each keeps its author, licence and original page for attribution.
-- ON CONFLICT keeps this safe if a car with the same address already exists.

WITH c AS (INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "createdAt", "updatedAt") VALUES ('dacia-logan-2023-1', 'Dacia', 'Logan', 2023, 550, 'Petrol'::"Fuel", 5, 90, 11.9, 175, '6-speed manual', 'FWD'::"Drive", NULL, 'Chișinău', 'Strada Calea Orheiului 105, Chișinău', 47.0542, 28.8496, 'Elena P.', 4.8, 124, 'The most practical saloon for the money: roomy, frugal and easy to drive in town or on the highway to the countryside. Its large boot swallows luggage for the whole family.', 'Cel mai practic sedan pentru banii lui: încăpător, economic și ușor de condus prin oraș sau pe drumul spre țară. Portbagajul mare înghite bagajele întregii familii.', 'Самый практичный седан за свои деньги: просторный, экономичный и простой в управлении в городе и на трассе. В большой багажник поместится багаж всей семьи.', ARRAY['Air conditioning', 'Bluetooth', 'Cruise control', 'Parking sensors', 'Large boot']::text[], CURRENT_TIMESTAMP - interval '0 minutes', CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING RETURNING "id")
