WITH c AS (INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "createdAt", "updatedAt") VALUES ('volkswagen-polo-2022-1', 'Volkswagen', 'Polo', 2022, 650, 'Petrol'::"Fuel", 5, 95, 10.8, 187, '5-speed manual', 'FWD'::"Drive", NULL, 'Bălți', 'Strada Mihai Eminescu 5, Bălți', 47.7861, 27.9149, 'Alexandru N.', 5.0, 38, 'A well-built small car that feels grown-up on the road. Quiet, economical and easy to handle, a favourite for first-time renters.', 'O mașină mică, bine construită, care se simte matură pe drum. Silențioasă, economă și ușor de manevrat, preferata celor care închiriază prima dată.', 'Качественно собранный небольшой автомобиль, который ведёт себя на дороге как взрослый. Тихий, экономичный и послушный — любимец тех, кто арендует впервые.', ARRAY['Air conditioning', 'Bluetooth', 'Apple CarPlay', 'Parking sensors', 'Cruise control']::text[], CURRENT_TIMESTAMP - interval '27 minutes', CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING RETURNING "id")
