INSERT INTO "CarPhoto" ("carId", "url", "position", "credit", "creditUrl") SELECT c."id", p.url, p.position, p.credit, p.credit_url FROM c, (VALUES ('/cars/nissan-qashqai-iii-f-25042024-960.jpg', 0, '© M 93 · CC BY-SA 3.0 de', 'https://commons.wikimedia.org/wiki/File:Nissan_Qashqai_(III)_%E2%80%93_f_25042024.jpg'), ('/cars/2024-nissan-qashqai-j12-img-1831-960.jpg', 1, 'Alexander-93 · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:2024_Nissan_Qashqai_(J12)_IMG_1831.jpg'), ('/cars/nissan-qashqai-j12-automesse-ludwigsburg-2022-1x7a5875-960.jpg', 2, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Qashqai_(J12)_Automesse_Ludwigsburg_2022_1X7A5875.jpg')) AS p(url, position, credit, credit_url);

WITH c AS (INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "createdAt", "updatedAt") VALUES ('nissan-leaf-2022-1', 'Nissan', 'Leaf', 2022, 850, 'Electric'::"Fuel", 5, 150, 7.9, 144, 'Single-speed', 'FWD'::"Drive", 270, 'Chișinău', 'Bulevardul Dacia 47, Chișinău', 46.9795, 28.8682, 'Igor P.', 5.0, 6, 'A quiet, fully electric family hatchback that costs very little to run. Enough range for a day of driving around Chișinău and back.', 'Un hatchback de familie complet electric, silențios și foarte ieftin de folosit. Autonomie suficientă pentru o zi întreagă de condus prin Chișinău.', 'Тихий полностью электрический семейный хэтчбек с минимальными расходами. Запаса хода хватит на целый день поездок по Кишинёву.', ARRAY['Climate control', 'Navigation', 'Fast charging', 'Rear camera', 'Heated seats']::text[], CURRENT_TIMESTAMP - interval '101 minutes', CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING RETURNING "id")
INSERT INTO "CarPhoto" ("carId", "url", "position", "credit", "creditUrl") SELECT c."id", p.url, p.position, p.credit, p.credit_url FROM c, (VALUES ('/cars/nissan-leaf-ze1-dsc-7096-960.jpg', 0, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7096.jpg'), ('/cars/nissan-leaf-ze1-dsc-7099-960.jpg', 1, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7099.jpg'), ('/cars/nissan-leaf-ze1-dsc-7097-960.jpg', 2, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7097.jpg')) AS p(url, position, credit, credit_url);

WITH c AS (INSERT INTO "Car" ("slug", "brand", "model", "year", "pricePerDay", "fuel", "seats", "horsepower", "acceleration", "topSpeed", "transmission", "drive", "range", "city", "pickupAddress", "pickupLat", "pickupLng", "hostName", "hostRating", "hostTrips", "description", "descriptionRo", "descriptionRu", "features", "createdAt", "updatedAt") VALUES ('nissan-leaf-2022-2', 'Nissan', 'Leaf', 2022, 850, 'Electric'::"Fuel", 5, 150, 7.9, 144, 'Single-speed', 'FWD'::"Drive", 270, 'Chișinău', 'Strada Calea Orheiului 105, Chișinău', 47.0542, 28.8496, 'Dumitru S.', 4.6, 32, 'A quiet, fully electric family hatchback that costs very little to run. Enough range for a day of driving around Chișinău and back.', 'Un hatchback de familie complet electric, silențios și foarte ieftin de folosit. Autonomie suficientă pentru o zi întreagă de condus prin Chișinău.', 'Тихий полностью электрический семейный хэтчбек с минимальными расходами. Запаса хода хватит на целый день поездок по Кишинёву.', ARRAY['Climate control', 'Navigation', 'Fast charging', 'Rear camera', 'Heated seats']::text[], CURRENT_TIMESTAMP - interval '102 minutes', CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING RETURNING "id")
INSERT INTO "CarPhoto" ("carId", "url", "position", "credit", "creditUrl") SELECT c."id", p.url, p.position, p.credit, p.credit_url FROM c, (VALUES ('/cars/nissan-leaf-ze1-dsc-7099-960.jpg', 0, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7099.jpg'), ('/cars/nissan-leaf-ze1-dsc-7097-960.jpg', 1, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7097.jpg'), ('/cars/nissan-leaf-ze1-dsc-7096-960.jpg', 2, 'Alexander Migl · CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Nissan_Leaf_(ZE1)_DSC_7096.jpg')) AS p(url, position, credit, credit_url);
